{"code":"import pandas as pd, statsmodels.formula.api as smf
x=pd.read_csv('data/explore.csv'); es=['vitamin_d','sleep_hours','steps_k','bmi','crp_level','dose_mg','age_decades','sodium_mmol','hdl','stress_index']
for e in es:
 d=x[['recovery_score',e,'hospital']].dropna(); m=smf.ols(f'recovery_score ~ {e} + C(hospital)',d).fit()
 print(e,round(m.params[e],4),round(m.pvalues[e],6),len(d),round(m.rsquared,3))"}
